def transform4(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]; seen=set()
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color: seen.add((yy,xx)); q.append((yy,xx))
        if len(cells)==1:
          y,x=cells[0]; nei=[grid[yy][xx] for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)) if 0<=yy<h and 0<=xx<w]; cnt=Counter(nei)
          dominant=[k for k,v in cnt.items() if v>=3 and k!=bg]
          replacement=dominant[0] if dominant else bg
          if not dominant:
            candidates=set(nei)-{bg,color}
            for k in candidates:
              for dy,dx in ((-1,-1),(-1,0),(0,-1),(0,0)):
                coords=((y+dy,x+dx),(y+dy,x+dx+1),(y+dy+1,x+dx),(y+dy+1,x+dx+1))
                if all(0<=yy<h and 0<=xx<w for yy,xx in coords) and all((yy,xx)==(y,x) or grid[yy][xx]==k for yy,xx in coords):
                  replacement=k; break
              if replacement!=bg: break
          out[y][x]=replacement
    return out

